"""Small Markdown helpers for the generated reference pages."""

from __future__ import annotations

import inspect
import json
from typing import TYPE_CHECKING, Any

import yaml
from pydantic_core import PydanticUndefined


if TYPE_CHECKING:
    from collections.abc import Iterable, Sequence

    from pydantic import BaseModel


GENERATED = (
    "<!-- Generated by scripts/generate.py from the code and catalog/; do not edit. -->"
)
SECTIONS = ("Attributes:", "Args:", "Returns:", "Raises:")


def docstring(obj: object) -> str:
    """An object's own docstring without its Google-style sections.

    Args:
        obj: A class or module.

    Returns:
        The docstring's prose, dedented; empty if it has none.
    """
    text = inspect.cleandoc(getattr(obj, "__doc__", None) or "")
    kept = []
    for paragraph in text.split("\n\n"):
        if paragraph.startswith(SECTIONS):
            break
        kept.append(paragraph)
    return "\n\n".join(kept)


def table(header: Sequence[str], rows: Iterable[Sequence[str]]) -> str:
    """A Markdown table.

    Args:
        header: Column titles.
        rows: Cells, one sequence per row.

    Returns:
        The table, or an empty string when there are no rows.
    """
    body = [_row(row) for row in rows]
    if not body:
        return ""
    return "\n".join([_row(header), _row(["---"] * len(header)), *body])


def facts(rows: Iterable[Sequence[str]]) -> str:
    """A list of `label: value` facts.

    Args:
        rows: `(label, value)` pairs.

    Returns:
        One bullet per fact, the label in bold.
    """
    return "\n".join(f"- **{label}:** {_cell(value)}" for label, value in rows)


def _row(cells: Sequence[str]) -> str:
    """One Markdown table row.

    Args:
        cells: The row's cells.

    Returns:
        The row, cells escaped.
    """
    return "| " + " | ".join(_cell(c) for c in cells) + " |"


def _cell(text: str) -> str:
    """A table cell's text on one line, with `|` escaped.

    Args:
        text: The cell's text.

    Returns:
        The escaped text.
    """
    return " ".join(text.replace("|", "\\|").split())


def code(value: object) -> str:
    """Inline code; JSON-like values in YAML flow style.

    Args:
        value: A string or a YAML value.

    Returns:
        The value in backticks.
    """
    text = value if isinstance(value, str) else flow(value)
    return f"`{text}`"


def flow(value: object) -> str:
    """A value in one line of YAML flow style.

    Args:
        value: A YAML value.

    Returns:
        E.g. `{use: resize, size: 256}`.
    """
    return (
        yaml.safe_dump(
            _plain(value), default_flow_style=True, sort_keys=False, width=10_000
        )
        .strip()
        .removesuffix("...")
        .strip()
    )


def _plain(value: Any) -> Any:
    """Tuples as lists, so YAML writes plain flow sequences.

    Args:
        value: A JSON-compatible value.

    Returns:
        The value with only JSON types.
    """
    return json.loads(json.dumps(value))


def options_table(options: type[BaseModel], per_run: frozenset[str]) -> str:
    """A table of a model's fields: name, type, default and description.

    Args:
        options: A pydantic model, e.g. a component's `Options`.
        per_run: Field names a caller may override per run.

    Returns:
        The table, or an empty string for a model without fields.
    """
    schema = options.model_json_schema()
    properties = schema.get("properties", {})
    defs = schema.get("$defs", {})
    rows = []
    for name, info in options.model_fields.items():
        description = info.description or ""
        if name in per_run:
            description = f"**Per run.** {description}"
        rows.append(
            [
                code(name),
                schema_type(properties.get(name, {}), defs),
                default(info.default, info.is_required()),
                description,
            ]
        )
    return table(["Option", "Type", "Default", "Description"], rows)


def default(value: object, required: bool) -> str:
    """How a field's default reads in a table.

    Args:
        value: The default.
        required: Whether the field has none.

    Returns:
        `required`, `not set` for None, or the value as code.
    """
    if required or value is PydanticUndefined:
        return "required"
    if value is None:
        return "not set"
    return code(value)


def schema_type(prop: dict[str, Any], defs: dict[str, Any]) -> str:
    """A JSON Schema property's type in a few words, with its limits.

    Args:
        prop: The property's schema.
        defs: The schema's `$defs`, for references.

    Returns:
        E.g. `integer > 0`, `` `bilinear` or `bicubic` ``, `list of string`.
    """
    if "$ref" in prop:
        target = defs.get(prop["$ref"].rsplit("/", 1)[-1], {})
        if "enum" in target or ("type" in target and target["type"] != "object"):
            return schema_type(target, defs)
        return str(target.get("title", "object"))
    if "const" in prop:
        return code(prop["const"])
    if "enum" in prop:
        return " or ".join(code(v) for v in prop["enum"])
    if "anyOf" in prop:
        kinds = [schema_type(p, defs) for p in prop["anyOf"] if p.get("type") != "null"]
        return " or ".join(kinds)
    kind = prop.get("type", "any")
    if kind == "array":
        if "prefixItems" in prop:
            items = ", ".join(schema_type(p, defs) for p in prop["prefixItems"])
            return f"[{items}]"
        return f"list of {schema_type(prop.get('items', {}), defs)}"
    if kind == "object":
        values = prop.get("additionalProperties")
        if isinstance(values, dict):
            return f"mapping of {schema_type(values, defs)}"
        return "mapping"
    limits = [
        f"{symbol} {prop[key]}"
        for key, symbol in (
            ("exclusiveMinimum", ">"),
            ("minimum", "≥"),
            ("exclusiveMaximum", "<"),
            ("maximum", "≤"),
        )
        if key in prop
    ]
    return " ".join([str(kind), ", ".join(limits)]).strip()
